function rollEventOutcome(choice) {
  let r = Math.random();
  for (const o of choice.outcomes) {
    if (r < o.p) return o;
    r -= o.p;
  }
  return choice.outcomes[choice.outcomes.length - 1];
}

function instantiateTrait(def, tier) {
  const inst = { ...def, tier };
  if (def.id === "deadZone") {
    inst.zone = Math.floor(Math.random() * 9);
    inst.oppositeZone = OPPOSITE[inst.zone];
    inst.desc = `${ZONE_LABELS[inst.zone]} 컨택 +15% / ${ZONE_LABELS[inst.oppositeZone]} -15%`;
  }
  return inst;
}

function rollTraitChoices(owned, tier, isPitcher) {
  const normalPool = isPitcher ? PITCHER_NORMAL_TRAIT_DEFS : NORMAL_TRAIT_DEFS;
  const majorPool = isPitcher ? PITCHER_MAJOR_TRAIT_DEFS : MAJOR_TRAIT_DEFS;
  const pool = (tier === "major" ? majorPool : normalPool).filter(
    (d) => tier === "major" || !owned.some((o) => o.id === d.id)
  );
  const shuffled = [...pool].sort(() => Math.random() - 0.5).slice(0, 3);
  return shuffled.map((d) => instantiateTrait(d, tier));
}

// ============ 유틸 ============
const rand = () => Math.random();
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
// 유인구(존 밖) 추격 확률.
// 예전엔 eye 기준 고정값(약 15%)이라 유인구가 사실상 공짜 볼이었음 -> 투수의 승부구로 격상.
//   - 2스트라이크면 플레이트를 보호해야 하니 크게 따라나감 / 3볼이면 참음
//   - 변화구(controlMod 낮은 = 크게 휘는 공)일수록 잘 속음
//   - 구위가 높을수록 판단이 늦어 더 속음
function chaseChance(eye, balls, strikes, pitch, stuffFactor = 1, fouls = 0) {
  let p = clamp(((100 - eye) / 100) * 0.42, 0.05, 0.55);
  p += Math.min(0.12, fouls * 0.04); // 커트가 쌓이면 조급해져 유인구에 더 속음
  if (strikes === 2) p += 0.20; // 밸런스: +0.30은 투수 과우위(시뮬 피안타 .266)
  if (balls === 3) p -= 0.15;
  else if (balls > strikes) p -= 0.08;
  const breaking = clamp((1.0 - (pitch?.controlMod ?? 1)) / 0.25, 0, 1);
  p += breaking * 0.12;
  p += (stuffFactor - 1) * 0.15;
  return clamp(p, 0.03, 0.85);
}
const tierLabel = (pct) => (pct >= 45 ? "유력" : pct >= 20 ? "보통" : "낮음");
// 선구안(eye)이 높을수록 확률 정보가 정밀해짐 - 성장 체감을 화면에 직접 드러내는 장치
//   eye < 60 : 티어만(유력/보통/낮음)
//   eye 60~79: 티어 + 10% 단위 근사치
//   eye >= 80: 실제 % 표시
const probLabel = (pct, eye = 0) => {
  if (pct == null) return "";
  if (eye >= 80) return `${Math.round(pct)}%`;
  if (eye >= 60) return `${tierLabel(pct)} ~${Math.round(pct / 10) * 10}%`;
  return tierLabel(pct);
};
const powerBolts = (rating) => (rating >= 70 ? "⚡⚡⚡" : rating >= 50 ? "⚡⚡" : "⚡");
const HIT_ORDER = ["out", "single", "double", "triple", "homerun"];
// 투수 몰입 게이지: 연속 아웃 잡을수록 제구 안정(리듬 탄다), 안타/볼넷 허용시 리셋
function pitcherControlBonus(streak, thresholdBonus = 0, multiplier = 1) {
  const s = streak + thresholdBonus;
  let bonus = 0;
  if (s >= 6) bonus = 15;
  else if (s >= 3) bonus = 8;
  return bonus * multiplier;
}
// 투수 특성들을 합산해서 실제 수치 보정값으로 변환
function pitcherTraitEffects(traits) {
  const eff = {
    controlDelta: 0, stuffDelta: 0, wildPitchDelta: 0,
    streakThresholdBonus: 0, streakMultiplier: 1, resetKeepRatio: 0,
    pinpointPenaltyOverride: null, noPinpointDifficulty: false, zonePitchingPenalty: 0,
  };
  for (const t of traits) {
    switch (t.id) {
      case "controlType": eff.controlDelta += 8; break;
      case "pinpointSense": eff.pinpointPenaltyOverride = 0.8; break;
      case "quickSettle": eff.streakThresholdBonus += 1; break;
      case "stuffType": eff.stuffDelta += 10; break;
      case "steadyMound": eff.resetKeepRatio = Math.max(eff.resetKeepRatio, 0.5); break;
      case "fireballer": eff.stuffDelta += 20; eff.controlDelta -= 15; eff.wildPitchDelta += 0.05; break;
      case "iceInVeins": eff.streakMultiplier *= 1.5; break;
      case "gambler": eff.noPinpointDifficulty = true; eff.zonePitchingPenalty += 10; break;
      default: break;
    }
  }
  return eff;
}
// 그라인드 보너스: 타석에서 버틴 투구수가 쌓이면 컨택 결과의 하한선을 올려줌 (5구+ 최소안타, 10구+ 최소홈런)
function upgradeByGrind(outcome, pitchesSeen) {
  if (!HIT_ORDER.includes(outcome)) return outcome;
  let idx = HIT_ORDER.indexOf(outcome);
  if (pitchesSeen >= 10) idx = Math.max(idx, HIT_ORDER.indexOf("homerun"));
  else if (pitchesSeen >= 5) idx = Math.max(idx, HIT_ORDER.indexOf("single"));
  return HIT_ORDER[idx];
}
const EXP_TABLE = { out: 4, strikeout: 3, walk: 6, single: 10, double: 18, triple: 26, homerun: 40 };
// 투수 시점 경험치: 아웃/삼진이 성과, 출루 허용은 소량(경험은 쌓임)
const expToNext = (level) => 50 + (level - 1) * 25;

// 표시되는 후보확률에 읽기노이즈 추가 - eye 낮으면 화면 %랭킹이 실제와 어긋날 수 있음
// (제구=순수 실행력, eye=순수 읽기실력으로 분리하기 위함. 실제 투구 결과는 이 노이즈의 영향을 받지 않음)
function applyReadNoise(dist, eye) {
  const noiseMag = ((100 - eye) / 100) * 0.6;
  const noisy = {};
  for (const [z, p] of Object.entries(dist)) {
    const factor = 1 + (rand() * 2 - 1) * noiseMag;
    noisy[z] = Math.max(0.01, p * factor);
  }
  return noisy;
}

function sampleFromDistribution(dist) {
  const entries = Object.entries(dist);
  const total = entries.reduce((s, [, p]) => s + p, 0);
  let r = rand() * total;
  for (const [z, p] of entries) { r -= p; if (r <= 0) return Number(z); }
  return Number(entries[entries.length - 1][0]);
}

function rollActualZone(targetZone, control, pitchControlMod) {
  return sampleFromDistribution(computeDistribution(targetZone, control, pitchControlMod));
}

// 특성 적용해서 실전 스탯 산출 (곱연산 스택 + 상한)
function getEffectiveBatter(base, traits, ctx) {
  let zoneRating = [...base.zoneRating];
  let eye = base.eye;
  let contactMult = 1;
  let hrMult = 1;
  let missMult = 1;
  let wasteContactEnabled = false;
  let wasteContactPenalty = 1;

  for (const t of traits) {
    switch (t.id) {
      case "badBallHitter":
        wasteContactEnabled = true;
        wasteContactPenalty = 0.85;
        break;
      case "clutch":
        contactMult *= ctx.runnersOn ? 1.1 : 0.95;
        break;
      case "earlyCount":
        contactMult *= ctx.balls === 0 && ctx.strikes === 0 ? 1.15 : 0.95;
        break;
      case "twoStrikeApproach":
        if (ctx.strikes === 2) missMult *= 0.7;
        break;
      case "deadZone":
        zoneRating = zoneRating.map((v, i) =>
          i === t.zone ? clamp(v + 15, 0, 100) : i === t.oppositeZone ? clamp(v - 15, 0, 100) : v
        );
        break;
      case "monsterPower":
        hrMult *= 1.8;
        missMult *= 1.4;
        break;
      case "eagleEye":
        eye = 100;
        contactMult *= 0.8;
        break;
      case "walkMachine":
        eye = clamp(eye + 20, 0, 100); // 볼 판정 유리 (eagleEye=100 만큼은 아니지만 후보 압축)
        missMult *= 0.85; // 스윙 안정성↑ (헛스윙 확률 감소)
        hrMult *= 0.75; // drawback: 장타 파워 -25%
        break;
      default:
        break;
    }
  }
  contactMult = clamp(contactMult, 0.5, 1.5);
  zoneRating = zoneRating.map((v) => clamp(v * contactMult, 0, 100));
  return { zoneRating, eye, hrMult, missMult, wasteContactEnabled, wasteContactPenalty, widthCap: base.widthCap ?? 1 };
}

// AI 투수 의사결정.
// 덱빌딩 구조에서는 타석이 길어질수록 타자가 유리해진다(파울마다 카드 드로우 -> 손패 선택지 증가).
// 그래서 AI 투수는 "빨리 끝내려는 압박"을 가져야 함:
//   - 타석이 길어질수록: 유인구 비중↓(질질 끌지 않음), 핀포인트↑, 구위형 구종↑(삼진 노림)
//   - 체력이 떨어질수록: 제구 좋은 구종으로 도망(구위 승부 포기)
function aiPickPitch(effBatter, balls, strikes, opts = {}) {
  const { pitchesThisPA = 0, stamina = 100 } = opts;
  // 약점 zone 쏠림 완화(지수<1로 평탄화) - 안그러면 "약점 하나만 노리면 됨"이 되어버림
  const weights = effBatter.zoneRating.map((v) => Math.pow(100 - v, 0.6));
  const hitterAhead = balls > strikes;
  const dangerLevel = effBatter.zoneRating.reduce((a, b) => a + b, 0) / 9;
  // 타석이 길어질수록 유인구로 끄는 걸 줄임(타자 손패만 좋아지므로)
  const dragPenalty = Math.min(0.22, pitchesThisPA * 0.045);
  const baseWaste = (hitterAhead ? 0.12 : 0.28) - dragPenalty;
  // 하한 10%: 타석이 길어져도 최소한의 볼 배합은 유지(전부 스트라이크존이면 볼넷이 사라져 야구답지 않음)
  const wasteChance = clamp(strikes === 2 && dangerLevel > 55 ? baseWaste + 0.18 : baseWaste, 0.10, 0.5);
  let targetZone;
  if (rand() < wasteChance) {
    targetZone = 9;
  } else {
    const total = weights.reduce((a, b) => a + b, 0);
    let r = rand() * total;
    targetZone = weights.findIndex((w) => (r -= w) < 0);
    if (targetZone < 0) targetZone = 4;
  }
  // 구종 선택: 랜덤이 아니라 상황 가중
  //   urgency(타석 지연) 높으면 위력적인(power 큰) 구종, 지치면 제구 좋은(controlMod 큰) 구종
  const urgency = Math.min(1, pitchesThisPA / 6) * (strikes === 2 ? 1.25 : 1);
  const tired = clamp((70 - stamina) / 70, 0, 1);
  const pitchWeights = PITCH_TYPES.map((p) => {
    // 구종별 성향을 0~1로 정규화해야 차이가 실제로 드러남(원값 그대로면 기본값에 묻힘)
    const powerNorm = clamp((p.power - 45) / 30, 0, 1);        // 직구1.0 슬라0.5 체인0.33 커브0
    const controlNorm = clamp((p.controlMod - 0.75) / 0.25, 0, 1); // 직구1.0 체인0.6 슬라0.4 커브0
    return 0.3 + urgency * powerNorm * 2.6 + tired * controlNorm * 2.0;
  });
  const ptTotal = pitchWeights.reduce((a, b) => a + b, 0);
  let pr = rand() * ptTotal;
  let ptIdx = pitchWeights.findIndex((w) => (pr -= w) < 0);
  if (ptIdx < 0) ptIdx = 0;
  const pitch = PITCH_TYPES[ptIdx];
  // 타석이 길수록 정밀하게 승부
  const pinpointChance = clamp((strikes === 2 ? 0.6 : balls >= 3 ? 0.15 : 0.35) + pitchesThisPA * 0.05, 0.1, 0.85);
  const mode = rand() < pinpointChance ? "pinpoint" : "zone";
  return { targetZone, pitch, mode };
}

// 폭투: 정상 제구분포와 별개로 일정확률로 완전히 랜덤한 곳(볼 포함)으로 감
// 실투 여부를 호출부가 알 수 있게 out 파라미터로 표시(연출/보너스용)
function rollActualZoneWithWildPitch(targetZone, control, pitchControlMod, wildPitchChance, out) {
  if (rand() < wildPitchChance) {
    if (out) out.wild = true;
    return Math.floor(rand() * 10);
  }
  if (out) out.wild = false;
  return rollActualZone(targetZone, control, pitchControlMod);
}

// AI 타자의 노림수 분포 산출.
// 예전엔 "직전 투구 존을 eye% 확률로 그대로 노림"이라 투수 입장에서 딜레마가 없었음(같은 곳만 안 던지면 됨).
// 이제는 (1) 최근 패턴 누적 (2) 타자 강점존 (3) 카운트 상황 (4) 노이즈 를 섞어 분포를 만든다.


function zoneCandidateCount(eye) {
  return clamp(Math.round(6 - (eye * 5) / 100), 1, 6);
}
function pitchCandidateCount(eye) {
  return clamp(Math.round(4 - (eye * 3) / 100), 1, 4);
}
// 확률분포에서 상위 N개 zone을 후보로 선택 (target은 항상 최고 확률이라 항상 포함됨)
function buildZoneCandidates(dist, count) {
  return Object.entries(dist)
    .sort((a, b) => b[1] - a[1])
    .slice(0, count)
    .map(([z]) => Number(z));
}
function buildPitchCandidates(actualPitchId, count) {
  const result = new Set([actualPitchId]);
  const rest = PITCH_TYPES.map((p) => p.id).filter((id) => id !== actualPitchId).sort(() => rand() - 0.5);
  for (const id of rest) {
    if (result.size >= count) break;
    result.add(id);
  }
  return [...result];
}

// zone별 난이도: 코너(핀포인트)일수록 헛스윙/파울 확률↑, 정중앙(그루브)은 안정적
const ZONE_DIFFICULTY = [1.3, 1.1, 1.3, 1.1, 0.8, 1.1, 1.3, 1.1, 1.3];

// zone/pitch/eff 받아서 컨택 결과 산출. mode: "safe"(존스윙, 단타위주 안정) | "guess"(게스히팅, 정확히 맞히면 대박)
// zone 인덱스(0~8) -> 3x3 그리드상 위치(%). 9(유인구)는 존 바깥 아래쪽
function zoneGridPos(z) {
  if (z === 9) return { x: 50, y: 120 };
  const col = z % 3, row = Math.floor(z / 3);
  return { x: (col + 0.5) * 33.33, y: (row + 0.5) * 33.33 };
}
// 두 zone 사이 그리드 거리 (조준-실제 미스매치 정도 측정용)
function zoneDistance(a, b) {
  if (a === b) return 0;
  if (a === 9 || b === 9) return 2.5;
  const ca = a % 3, ra = Math.floor(a / 3);
  const cb = b % 3, rb = Math.floor(b / 3);
  return Math.hypot(ca - cb, ra - rb);
}

// deception(구위/변화) 판정: 배트 중심을 비끼게 만들어 정타를 봉쇄.
// 성공하면 powerMult로 타구 질을 직접 깎는다(헛스윙과는 별개 축 - "맞아도 죽는 타구").
function deceptionRoll(stuff, pitch, staminaF = 1, batterContact = 50) {
  const breaking = clamp((1.0 - (pitch?.controlMod ?? 1)) / 0.25, 0, 1); // 커브1.0 슬라0.6 체인0.4 직구0
  const effStuff = clamp(stuff * staminaF, 1, 130);
  // 구위 + 변화도 vs 타자 컨택 능력
  const edge = (effStuff - batterContact) / 100 + breaking * 0.28;
  const chance = clamp(0.12 + edge * 0.55, 0.04, 0.62);
  return { hit: rand() < chance, chance };
}
function resolveContact(eff, zone, pitch, isWaste, mode = "safe", extraDifficulty = 0, speedMode = "strategy", swingQuality = 0.5, cutSwing = false, powerMult = 1, outBias = 0, gradeMult = 1) {
  const difficulty = (isWaste ? 1 : ZONE_DIFFICULTY[zone] ?? 1) + extraDifficulty;
  const zoneRating = isWaste ? (eff.zoneRating[4] ?? 40) * 0.5 : eff.zoneRating[zone] ?? 40;
  const wastePenalty = isWaste ? eff.wasteContactPenalty : 1;
  let power = clamp(((zoneRating * 0.6 + (100 - pitch.power) * 0.4) / 100) * wastePenalty * powerMult, 0, 1);
  let missFactor = eff.missMult * difficulty;
  let hrBoost = eff.hrMult;

  if (mode === "safe") { power = Math.min(power, 0.55); missFactor *= 0.75; }
  else if (mode === "guess") { power = Math.min(power * 1.15, 1); missFactor *= 0.9; hrBoost *= 1.15; }

  // 게스히터(전략모드) vs 피지컬형(리얼타임모드): 하이리스크하이리턴 vs 로우리스크 안정형
  if (speedMode === "strategy") { power *= 1.15; missFactor *= 1.15; }
  else if (speedMode === "realtime") { power *= 0.85; missFactor *= 0.8; }

  // 타격 타이밍 미니게임(리얼타임모드 전용) 퀄리티 반영. 0.5=중립(미니게임 미사용시 기본값), 1=완벽타이밍, 0=완전히 놓침
  power *= clamp(0.5 + swingQuality * 1.0, 0.35, 1.5);
  missFactor *= clamp(1.5 - swingQuality * 1.0, 0.5, 1.5);

  // 커트(체크스윙): 궤적 읽고 안전하게 짧게 끊어치는 선택 - 장타력은 확 죽이지만 헛스윙/삼진 위험은 크게 낮춤
  if (cutSwing) { power = Math.min(power, 0.32); missFactor *= 0.45; hrBoost = Math.min(hrBoost, 0.5); }

  const pMiss = clamp(0.30 - 0.16 * power, 0.06, 0.45) * missFactor;
  const pFoul = 0.30;
  const r = rand();
  if (r < pMiss) return { outcome: "swingMiss", power };
  if (r < pMiss + pFoul) return { outcome: "foul", power };
  // 인플레이: 아웃 여부 먼저 (BABIP ~.300 반영), 그 다음 안타 등급
  const pOut = clamp(0.80 - power * hrBoost * 0.42 + outBias, 0.32, 0.85);
  if (rand() < pOut) return { outcome: "out", power };
  const q = rand() * power * hrBoost * gradeMult;
  if (q > 0.58) return { outcome: "homerun", power };
  if (q > 0.40) return { outcome: "triple", power };
  if (q > 0.24) return { outcome: "double", power };
  return { outcome: "single", power };
}

