    cut:     { label: "커트",   color: "#a8b8ac", hint: "단독 사용 — 무조건 파울 + 카드 1장", solo: true },
    focusMod:{ label: "집중",   color: "#ffb000", hint: "빗나가도 컨택 시도 가능" },
